OUTSIDE_CUMULATIVE = ['ANTENNA_343', 'ANTENNA_344', 'ANTENNA_345', 'ANTENNA_347', 'ANTENNA_348', 'ANTENNA_349', 'ANTENNA_381', 'ANTENNA_382', 'ANTENNA_383', 'ANTENNA_384', 'ANTENNA_434', 'ANTENNA_435', 'ANTENNA_49', 'ANTENNA_50', 'ANTENNA_506', 'ANTENNA_507', 'ANTENNA_51', 'ANTENNA_519', 'ANTENNA_562', 'ANTENNA_700', 'ANTENNA_792', 'ANTENNA_797']

def checked_export(netlist, inventory):
    result=check_added_antennas(netlist,inventory)
    assert result['new_diodes_exported']==len(inventory)
    assert not result['missing_diodes'] and not result['duplicate_diodes'] and not result['signal_connection_mismatches']
    return result

def record(net):
    return dict(master='sg13g2_antennanp',signal_terms=[dict(pin='A',type='SIGNAL',net=net)])

def rebind_inventory(cumulative,audit,baseline_netlist):
    assert audit['all_original_diodes_preserved']
    assert audit['functional_equivalence_by_identity_buffer_collapse']
    assert audit['antenna_protection_revalidation_required']
    assert audit['accepted'] is False
    assert set(audit['moves'])==set(EXPECTED)
    assert set(EXPECTED)-set(cumulative)==set(OUTSIDE_CUMULATIVE)
    # Prove every moved diode's original master and connection, including the
    # 22 original diodes not covered by the added-diode cumulative inventory.
    checked_export(baseline_netlist,{n:record(old) for n,(old,new) in EXPECTED.items()})
    checked_export(baseline_netlist,cumulative)
    result=deepcopy(cumulative)
    moved={}
    for name,(old,new) in EXPECTED.items():
        assert audit['moves'][name]==dict(master='sg13g2_antennanp',old_net=old,new_net=new)
        if name in result:
            cell=result[name]
            assert cell['master']=='sg13g2_antennanp'
            assert cell['signal_terms']==record(old)['signal_terms']
            cell['signal_terms']=record(new)['signal_terms']
            if 'terms' in cell:
                pins=[term for term in cell['terms'] if term['pin']=='A']
                assert pins==record(old)['signal_terms']
                pins[0]['net']=new
        moved[name]=record(new)
    assert len(result)==len(cumulative)
    return result,moved

def verify_moved_export(netlist,moved):
    assert moved=={n:record(new)for n,(old,new)in EXPECTED.items()}
    return checked_export(netlist,moved)
